class Solution {
  private static final int MOD = 1_000_000_007;

  public int numberOfStableArrays(int zero, int one, int limit) {
    long[][] endZero = new long[zero + 1][one + 1], endOne = new long[zero + 1][one + 1];
    for (int z = 1; z <= zero && z <= limit; z++) endZero[z][0] = 1;
    for (int o = 1; o <= one && o <= limit; o++) endOne[0][o] = 1;
    for (int z = 1; z <= zero; z++)
      for (int o = 1; o <= one; o++) {
        endZero[z][o] = (endZero[z - 1][o] + endOne[z - 1][o]) % MOD;
        if (z - limit - 1 >= 0)
          endZero[z][o] = (endZero[z][o] - endOne[z - limit - 1][o] + MOD) % MOD;
        endOne[z][o] = (endZero[z][o - 1] + endOne[z][o - 1]) % MOD;
        if (o - limit - 1 >= 0)
          endOne[z][o] = (endOne[z][o] - endZero[z][o - limit - 1] + MOD) % MOD;
      }
    return (int) ((endZero[zero][one] + endOne[zero][one]) % MOD);
  }
}
